["questFaction"] = "Horde",
["questText"] = {
["enUS"] = {
[96898] = {
["o"] = "Gather 12 Necrotic Crystal Fragments in Tirisfal Glades.",
["d"] = "It wasn't long ago that the citadel of Naxxramas bore down upon this city, intent on wiping the Forsaken off the map. Both the Forsaken and the Argent Dawn lost much that day to secure the future of the Forsaken.\r\n\r\nDuring the battle, the great necrotic focusing crystal mounted atop Naxxramas was shattered and its fragments were scattered all over this area. I suspect that is what the cultists are here for. Help me recover the fragments and deprive the Scourge of them.",
},
[92579] = {
["o"] = "Deliver Aonda's Written Report to Valennia Stormfist in Valanaar.",
["d"] = "For now it seems the pylon and the village are safe, so I'd like you to deliver this report to Valennia Stormfist in Valanaar, at the southeastern edge of the island. Valennia is the leader of the peacekeepers on the island and she needs to know what happened here.\r\n\r\nThe cult is expanding rapidly and the peacekeepers have avoided direct conflict until now, but those days are over. Valanaar will need to be ready for a fight.\r\n\r\nAt any rate, thank you. You'll always have friends in Shen'dar, N.",
},
[92595] = {
["o"] = "Listen to what Illaya Amberwind has to say.",
["d"] = "<Illaya smiles warmly at you.>\r\n\r\nI am glad you returned to speak with me, child of the winds. I knew it the first moment you walked into my presence, that you were strong in the skysight. Do you find this surprising? Even those who have not trained as a Shaman may possess the gift. \r\n\r\nCome, let us speak about the mandate of the Windshapers, the nature of our struggles on Zephras, and the plight of our people.",
},
[92643] = {
["o"] = "Find the cultist turncoat at the house just inside the highlands northwest of Valanaar.",
["d"] = "There is a turncoat amongst the Al'Aketh. They claim to know the cult's true intentions for the island and want to come in, but will only do so with assurances of protection.\r\n\r\nThis defector is hiding at a secluded residence just northwest of Valanaar inside the highlands. I need someone who can discreetly go there, find the traitor, and escort him back to us. This might be a trap, but if this information is as important as this traitor claims, it's worth some risk.",
},
[357] = {
["o"] = "Bring the Lich's Spellbook to Bethor Iceshard in the Undercity.",
["d"] = "There is a lich who dwells on the island in Brightwater Lake to the north.  Although he is a free-willed Forsaken, he believes all other Undead are Scourge slaves and has his minions attack anyone who approaches him.\n\nBut because he is Forsaken, the Queen will want him.  And if he is skilled in Necromancy, then his knowledge would be...quite useful to us.\n\nTo discover his identity and his talents, I must see his spellbook.  Steal into his camp and acquire it, then return to me.",
},
[744] = {
["o"] = "Collect 6 Azure Feathers and 6 Bronze Feathers, and bring them to Eyahn Eagletalon in Thunder Bluff.",
["d"] = "N, my brother soon stands before Chief Bloodhoof, and it is my honor to make his headdress for him.\n\nI want to ask a favor of you while I finish tanning these leather straps. There is not time for me to find enough feathers, and I was wondering, would you gather more for me?\n\nYou can find feathers of the correct size from the harpies residing far to the north and northwest of Thunder Bluff. I need only 6 azure and 6 bronze feathers to complete the design.",
},
[92468] = {
["o"] = "Bring the Rough Quartz to Windshaper Boros in Thendal Grove.",
["d"] = "Take this Rough Quartz from me and bring it to the one you call Windshaper Boro as proof of our meeting. He will craft a totem for you, and this shard will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast many others.\n\nBe patient, N. Remain strong. And seek wisdom. This is what the elements ask of you. In the end, you shall become one with the earth--respect it as it shall respect you.",
},
[92484] = {
["o"] = "Examine the Humming Recall Crystal then speak with Windshaper Boro in Thendal Grove.",
["d"] = "While you were away dealing with our vuldren problem, our resident Shaman trainer--Windshaper Boro--left this recall crystal for you. Please examine it, then speak with Boro just over yonder near the center of the village.",
},
[92516] = {
["o"] = "Slay 8 Hippogryph Youths, 6 Hippogryph Protectors and a Hippogryph Matriarch in the Shen'dar Highlands.",
["d"] = "A flock of Hippogryph have recently established nesting grounds southeast of Shen'dar Village and they've been wreaking havoc on travelers on the road. I need someone to head down there and thin them out for us.",
},
[93552] = {
["o"] = "Collect 15 Windstone Clusters from Raw Windstones in Thendal Grove.",
["d"] = "Windstones are a critical resource on Zephras Isle as they contain the raw, concentrated energy of the winds themselves. The wind elementals who used to live here on Zephras with us vanished a number of years ago, and since then, the magic that sustains this island is slowly fading. Not without limitations, the windstones are still a reliable energy source, and are incredibly valuable to us.\r\n\r\nYou'll find raw windstones scattered around the grove. Think you can help me harvest them?",
},
[96899] = {
["o"] = "Meet Leonid Barthalomew at Bandarion Keep in Tirisfal Glades.",
["d"] = "You've done a great thing for the cause of the Argent Dawn here today, and I thank you. I don't know how familiar you are with the fortress of Bandarion Keep, but my commander and I were headed that way to meet with the paladins that reside there. That was before we learned of the presence of the Cult of the Damned.\r\n\r\nIf you'd like to learn more about the Argent Dawn and our mission, seek out my commander at Bandarion Keep, to the northwest of here. I'll remain here to mop up the rest of this mess.",
},
[93090] = {
["o"] = "Speak with Ayessa Dawnsinger when you are prepared to leave Zephras Isle.",
["d"] = "Please extend my thanks to Ayessa for all that the Windshapers and your new friends from this \"Earthen Ring\" have done for Zephras Isle. I'm aware of the plan to take the Windshapers' shamans and leave the island, and your order has my blessing and well-wishes in this expedition.\r\n\r\nI can only hope that whatever solution the Windshapers find can truly provide us with the stability we've lacked these past years.\r\n\r\nWinds be with you, N.",
},
[97967] = {
["o"] = "Speak with Fenn Fairweather in Shen'dar Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.",
["d"] = "You might not think so, but your skill as a fisherman can actually come in handy at camp.\r\n\r\nI reckon I know someone that can teach you how to craft a Fish Bowl for your camp. You can use this fixture to help provide a bit of joy to yourself and your fellow adventurers. A happy adventurer is a strong adventurer and I'm sure your combat capabilities will reflect that.",
},
[92644] = {
["o"] = "Deliver the glowing crystal to Talanaanis Shadowsong in Valanaar.",
["d"] = "<You reach beneath the still-warm body of the turncoat cultist and recover a small, glowing blue crystal. It appears to be damaged, but it may still be important. High Elder Shadowsong may be interested in this.>",
},
[93951] = {
["o"] = "Collect 8 Hippogryph Down feathers in the Shen'dar Highlands.",
["d"] = "The hippogryphs that have taken up residence southwest of the village can be a nuisance, but they also present a rather unique opportunity to obtain their feathers. Many skyborne love to adorn their hair with vibrant plumes and the down feathers of a hippogryph are exceptionally vibrant and, more importantly, silky soft.\r\n\r\nIf you are heading that way, try and gather as many of the fallen feathers as you can from around their nesting grounds. Do be careful, as wild hippogryph are not tolerant of guests.",
},
[92947] = {
["o"] = "Slay 7 Al'Aketh Guardians, 7 Al'Aketh Spiritcallers, and 7 Al'Aketh Blademasters, then report to Hyusaa Quickbreeze at the Shrine of Akir.",
["d"] = "Everyone is here, good. I've just sent a few of my best fighters in through the front of the shrine to cause a bit of trouble and serve as a distraction, while I lead the the bulk of our forces in from the flank.\r\n\r\nIf all goes well, we should be able to punch through quickly and take out the High Priestess. As for you, get in there and start cracking skulls. Meet my second, Hyusaa Quickbreeze, near the steps to the shrine after you've caused some trouble.\r\n\r\nWinds guide you, hunter.",
},
[92708] = {
["o"] = "Listen to what Ayessa Dawnsinger has to say.",
["d"] = "The Windshapers have been hard at work trying to respond to the current crisis on Zephras Isle. We have made several surprising discoveries in our search for the missing wind spirits, and we are developing a plan of action that could help us gain the means to save the island.\r\n\r\nWe'll need strong young adventurers like yourself for this to work however. Please, if you have a moment, let us speak on this further.",
},
[92469] = {
["o"] = "Bring word of the Al'Aketh to Rorian the Dayseeker in Thendal Grove.",
["d"] = "You've done enough here, druid. I'll stay and clean up any stragglers down there.\r\n\r\nHead back to the Village and tell Rorian about the cult's presence. He will not be pleased.",
},
[92485] = {
["o"] = "Read the Folded Parchment then speak with Xyton Silverwind in Thendal Grove.",
["d"] = "While you were away dealing with our vuldren problem, our resident druid trainer--Xyton Silverwind--left this note for you. Read it as soon as you can, and then seek out Silverwind on the ground floor of this great tree just behind me.\r\n\r\nHeed his words and his counsel, he can teach you much.",
},
[92517] = {
["o"] = "Kill 10 Highlands Bandits and their leader, \"Badwind\" Bennic in the Shen'dar Highlands.",
["d"] = "There's a cave not far to the north, hidden behind a waterfall. It's well known to me that there's a group of bandits that are operating out of that cave. They were a problem for us before the cult arrived, but now they are a real terror. I can't spare the people to go and clear them out, unfortunately.\r\n\r\nI need you to go there and take care of them for me. Kill as many as you can, and if possible, take out their leader, the one they call \"Badwind\" Bennic. That cave is dangerous, so be careful.",
},
[97968] = {
["o"] = "Speak with Syriel Nightrain in Valanaar to learn to craft a camping item for your profession once you have shown proficiency in your skill.",
["d"] = "Looks to me like you've gained some skill in herbalism. Picking flowers isn't just for dilly-dallying, you know. It can be useful... and profitable.\r\n\r\nI reckon I know someone that can teach you how to craft an Incense Candle for your camp. High spirits are a key component to keeping healers and spellcasters in the fight, and an Incense Candle can provide a boost that magic users will surely appreciate.",
},
[94414] = {
["o"] = "Speak with Halaan Hawk-Eye and borrow his gift to view the anchor pylon in the distance.",
["d"] = "Greetings, young N. I oftentimes come here to look upon the ancient anchor pylon. Gifts from the spirits of the winds, they bind and sustain our island. Of late however, their magic has grown unstable and inconsistent.\r\n\r\nThey suffer no distress I can see. Their splendor has not changed.\r\n\r\nIf you'd like, I can lend you my gift to look upon them yourself.",
},
[92645] = {
["o"] = "Slay Commander Belguilos in the Gustberry Lowlands.",
["d"] = "This attack is going to be hard to repel unless we can take out the cult commander. Belguilos \"the Breaker\" they call her, and she's a veritable terror. She used to be a peacekeeper before the cult got out of control, and even then she was... off. As a cultist I can only imagine how much worse she could be now.\r\n\r\nI might just be sending you to your death, but someone needs to take Belguilos out if we are going to survive here. You can find her at the villa at the hill's base. Good luck, hunter.",
},
[92693] = {
["o"] = "Speak with Aamelia Windfield when you are ready to confront the bandit leader.",
["d"] = "You've done a lot to give us a fighting chance. Even if we die today, we'll at least know we gave it our best shot.\r\n\r\nThis is your last chance, stranger. If you want to head back to Valanaar and live another day, I wouldn't blame you.\r\n\r\nOn the other hand, if you really have a thing for lost causes just let me know when you are ready to go. We'll walk out there with our heads held high and whatever happens, happens.",
},
[407] = {
["o"] = "Take the Laced Pumpkin to the Captured Scarlet Zealot who is being held in the cellar of the Gallow's End Tavern.",
["d"] = "Harmless pumpkins, right?  Or so it would seem.  If we are to defeat Arthas's advances from the North and the Human infestation from the South we need to start realizing the full potential of our gift of undeath.\n\nWith a little ingenuity a simple pumpkin becomes an agent for our Dark Lady.  This pumpkin, laced with my latest formula, will prove to be quite a treat.\n\nYet another Scarlet Zealot has been captured and is being kept in the cellar of the Gallow's End Tavern.  Take this pumpkin to the fool.",
},
[92470] = {
["o"] = "Slay 8 Ursera Scavengers and collect the head of the den mother, Urs'anah in Thendal Grove.",
["d"] = "Rorian informed you that I've been watching you. I now offer you a test of resolve. However, be warned--it will send you into great danger.\r\n\r\nGo to the caves to the west. Thin out the ursera's numbers there, and find their matriarch, one the rangers call \"Urs'anah\". Put her down and bring me proof of her demise. Once you have done that, you will have taken an important step on your path.",
},
[92550] = {
["o"] = "Travel to the ruins of Falaath Village and slay 6 Al'Aketh Stormcallers, 4 Living Lightning and take the head of Commander Cyclas.",
["d"] = "Our best defense here might just be a strong offense. The advantage we now have is that we expect an attack is coming. What they won't expect is for us to hit them first.\r\n\r\nI've already asked a lot of you, but please head back over to Falaath Village. Kill as many cultists as you can and if you can get close enough, kill the commander and bring me his head. I'll stay here and organize the citizens and our few peacekeepers to prepare a defense... just in case you don't return.",
},
[96646] = {
["o"] = "Speak with Zerril Softbreeze in Shen'dar Village to learn to become a cook.",
["d"] = "So you want to learn more about camping, huh? Good for you, hunter. The first step any adventurer needs to take is to become a cook and learn how to make a campfire.\r\n\r\nCooking's not just about making tasty foods. It's also the foundation for your camp.",
},
[92598] = {
["o"] = "Use your Skysight racial ability at the Elemental Convergence in Thendal Grove.",
["d"] = "As a Windshaper, you have the ability to use the sacred skysight gifted to us by the elemental spirits. Travel to the standing stones to the northeast of the village. Find the elemental convergence there and use your gift.\r\n\r\nYou'll find that you may draw upon the skysight anywhere, but its boon is much more powerful if you do so in the presence of an elemental convergence. You may at times receive other bits of wisdom from the spirits that are drawn to such places of power, as well.",
},
[92646] = {
["o"] = "Take the portal to the Rohashi Spires overhead and join Elaadrin Evengale and Ayessa Dawnsinger in their confrontation with the High Priestess Lorthuna.",
["d"] = "Lorthuna fled up to the spires above using some sort of portal. Ayessa and Elaadrin went in after her. That was just a few moments ago.\r\n\r\nI'm afraid I took one too many hits and this is where I stay. Go through the portal, find Ayessa and help them stop Lorthuna.\r\n\r\nUnless that help that Elaadrin and Ayessa said they sent for arrives soon, you are on your own from here. Good luck, hunter.",
},
[93172] = {
["o"] = "Destroy 10 Wind Hollows in Shadowgale Forest.",
["d"] = "Most of the elves on this island seem to think that these woods are haunted, and they aren't wrong.\r\n\r\nAt the old ruins to the northeast, a strange type of ghost-like spirits gather. Some nights, you can almost hear them \"singing\". It's not like any song I've heard before, but it's definitely a song and it's... just so sad.\r\n\r\nI'm not sure why, but I think something terrible happened there at some point, and the spirits are trapped there somehow. If you are feeling brave, maybe you can help set them free?",
},
[408] = {
["o"] = "Kill 8 Wailing Ancestors and 8 Rotting Ancestors.\n\nKill Captain Dargol, and bring his skull to Magistrate Sevren in Brill.",
["d"] = "The Agamand Mills area has become a foothold for the Scourge.  Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered.  With Necromancy he has raised the ancestors of the Agamands and plans to use them against us.\n\nThis cannot pass, and you must stop it.  Travel to the Agamand Family Crypt and defeat the raised Agamand ancestors.\n\nAnd, bring me the skull of Captain Dargol.",
},
[92471] = {
["o"] = "Speak with Aetheen of the Gales in Thendal Grove.",
["d"] = "You may not realize this but everything you've done has been a trial of sorts. A test for what is to come for you. It's a big island out there, and Zephras needs spirited young adventurers such as yourself if we are to survive the trials our people face.\r\n\r\nThe one called Aetheen of the Gales is one of the leaders of our people here on Zephras Isle, and she has been watching you. She has a task that you must complete. Speak with her to learn more.",
},
[92551] = {
["o"] = "Collect 10 packs of Stolen Shen'dar Supplies from Falaath Village in the Shen'dar Highlands.",
["d"] = "I overheard you might be going to Falaath Village? While you are there, please keep an eye out for our stolen supply caches.\r\n\r\nThe Al'Aketh have been raiding our supply caravans carrying various goods such as food and windstones to and from the lowlands for months. They've been blaming the bandits, of course, but we all know that it all ends up in the same place. If there's any of that stuff left in Falaath, it would be a huge help if you could recover it.",
},
[97970] = {
["o"] = "Speak with Messana Crestwind in Shen'dar Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.",
["d"] = "Mining isn't the most glamorous, but it's good honest work and a fine profession for you to explore.\r\n\r\nI reckon I know someone that can teach you how to craft a Lodestone for your camp. Build one of these and everyone who wants to swing a sword will be eager to gather round your fire and soak up the extra \"oomph\" it can provide to increase their combat prowess.",
},
[98512] = {
["o"] = "Kill 10 Al'Aketh Assassins in the Shen'dar Highlands.",
["d"] = "You there, stranger. Get low and keep quiet. We are not alone here.\r\n\r\nI was on patrol near the border and noticed that there are a number of Al'Aketh skulking around the house just up the hill there to the north. I don't know what they are doing here, but it can't be good.\r\n\r\nIf you want to make yourself useful, get in there and take them out. I'll wait here and watch your back.",
},
[361] = {
["o"] = "Find Yvette Farthing, and deliver to her the letter from Thurman Agamand.",
["d"] = "This is a letter written by Thurman, the eldest son of Gregor Agamand.  It is addressed to an Yvette Farthing, though it does not appear to have reached her...",
},
[92679] = {
["o"] = "Listen to what Alvarion Windfield has to say and find Aamelia Windfield at the Windfield Orchard.",
["d"] = "H--Hello, stranger. You have the look of a capable adventurer about you. I...\r\n\r\n<The Skyborne man winces, clearly suffering terrible pain>\r\n\r\n...I was wondering if you were seeking employment? I came here to Valanaar to recruit fighters to help save my farm. If you are interested, please go find my wife Aamelia Windfield at our orchard to the west of Valanaar, in the lowlands.",
},
[409] = {
["o"] = "Obtain a Candle of Beckoning.\n\nSummon Lillith Nefara and kill her.\n\nReturn to Gunther on his island.",
["d"] = "You say you are not bound by the will of the Lich King, and the enchantment Bethor placed upon my book corroborates this.  But before I believe you I must have proof that you are enemy to the Scourge.\n\nThere is an old, bloody altar just off the southern coast of this island.  it is used by a powerful Scourge agent, Lillith Nefara.\n\nTake a Candle of Beckoning from this crate here.  Light it on the altar and Lillith will awake.  Destroy Lillith, and I will believe you are the Lich King's foe.",
},
[92472] = {
["o"] = "Report to Constable Aonda in Shen'dar Village.",
["d"] = "One of the most pervasive threats on Zephras Isle is the Al'Aketh Cult. They are religious zealots devoted to the worship of the supposed elemental ruler of Skywall, Al'Akir the Windlord. They are brutal, single-minded, and their power and ambitions are growing more deadly by the day.\r\n\r\nYour path will soon take you to Shen'dar Village to the south. Present yourself to Constable Aonda when you arrive. The cult threatens Shen'dar and they are in need of aid. Tell Aonda that I sent you.",
},
[95803] = {
["o"] = "Bring the head of Rudolph Gelhardt to Sylvanas Windrunner in the Undercity.",
["d"] = "Now that we've claimed the head of the tarnished commander, I need you to deliver it to the Undercity. Sylvanas Windrunner mistrusts us greatly, and all but openly disparages us.\r\n\r\nDeliver Rudolph Gelhardt's head to the Dark Lady. Show her that we tend to our own house and are devoted to the prosperity of the forsaken.",
},
[94050] = {
["o"] = "Speak to Quel'dora Quickgale in Valanaar.",
["d"] = "You now have the power to tame a pet, but you must also gain the skills to train it. For this, there is none better than my sister, Quel'dora. She will give you the ability to train your new pet. \r\n\r\nGo with the winds, young hunter.",
},
[97891] = {
["o"] = "Bring the Unstable Potion to Doctor Martin Felben in the Apothecarium within the time limit.",
["d"] = "You! Quickly, I need you to bring this potion across the slime canal to Doctor Martin Felben in the Apothecarium!\r\n\r\nIt has a very limited shelf life, and no I can't go myself, my knees rattle and pop out if I attempt to run.\r\n\r\nJust another lovely side effect of undeath, apparently.\r\n\r\nBut we're wasting time! Here, take this and go!\r\n\r\n<Alessandro makes a shooing motion.>",
},
[93317] = {
["o"] = "Collect 6 pieces of Windsong Crawler Meat.",
["d"] = "Are you familiar with Windsong Crawlers? You see, these crabs are native only to Windsong Lake here on Zephras, and they are only able to be harvested a few weeks of the year.\r\n\r\nWith all of the cult activity of late, I've not been able to get out to the lake to harvest them, and our window is rapidly closing. I'd be appreciative if you could go and gather some for me. They can generally be found along the shorelines around the lake and in rivers.\r\n\r\nDo be careful though, they are meaner than they look!",
},
[5722] = {
["o"] = "Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest.",
["d"] = "The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She'd like Maur's body found--if it still exists--and any signs of what he found while attempting to speak to the troggs.\n\nReturn to Magatha any items of interest, and I'm sure she would be very generous in her reward.\n\nAgain, seek the Chasm in the darkest areas of Orgrimmar.",
},
[5723] = {
["o"] = "Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff.",
["d"] = "Beneath the city of Orgrimmar, stout creatures known as troggs started coming to the surface from deep below the lava filled tunnels. In her ever-benevolence, Magatha sought to make peace with the creatures, but they turned on her diplomats, killing them. She will not allow such treatment of the tauren people and now consider the creatures a threat to all of the Horde.\n\nShe asks that you put an end to this trogg threat before it overwhelms the Horde from below. Find Ragefire Chasm and destroy them all.",
},
[97955] = {
["o"] = "Speak with Nurse Neela in Brill to learn to craft a camping item for your profession once you have shown proficiency in your skill.",
["d"] = "So you've taken up First Aid? That's an honorable... and pragmatic pursuit as a paladin.\r\n\r\nI reckon I know someone that can teach you how to craft a First Aid Kit for your camp. Injuries are a reality in the world of adventuring and offering some much-needed healing at your camp could even save lives.",
},
[5725] = {
["o"] = "Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.",
["d"] = "Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with... lesser vision.\n\nA sect of the Shadow Council hidden in caverns below Orgrimmar known as the Searing Blade are a prime example. The Lady tells me that members of the Searing Blade have come into the possession of two powerful spell books--she would like to \"borrow\" these books from them. You will get them for her.",
},
[5726] = {
["o"] = "Bring a Lieutenant's Insignia to Thrall in Orgrimmar.",
["d"] = "One thing I will not tolerate are traitors in our midst, N. But I would be a fool to play my hand so early--it would not sufficiently cut the corruption out of our lands and only cause the infection to grow worse.\n\nBut you, a young adventurer, could go places my agents could not... could learn the truth... could find the true head of the beast.\n\nIf you are brave enough, then enter Skull Rock to the east of Orgrimmar, find a lieutenant's insignia off one of the Burning Blade there, and return to me.",
},
[362] = {
["o"] = "Slay Devlin Agamand, and bring Devlin's Remains to Coleman Farthing in Brill.",
["d"] = "Devlin Agamand was the younger of two sons in the Agamand family, and in life the two could not be more different.  Thurman was tall and gentle while his younger brother was weak and sharp tongued.\n\nWhen Agamand Mills fell to the Plague, I was not surprised to hear that Devlin was quick to succumb.  His mad chattering can still be heard near the road leading to the Agamand Mills.\n\nI'm collecting the remains of the Agamands, and I want poor Devlin.  Find him, destroy him, and bring me his bones.",
},
[98545] = {
["o"] = "Deliver the Sealed Letter to Glix Xizzix in the Undercity.",
["d"] = "Since you are here, I'd like you to deliver this letter to an old friend of mine in the Undercity. I'd deliver myself but I have a somewhat colorful history with the Dark Lady, and it would be better if a neutral third party made the delivery.\r\n\r\nYou are looking for a goblin named Glix Xizzix in the Trade Quarter area of the Undercity. I'm sure he'd be happy to compensate you for your time.\r\n\r\n<Leonid lets out a low chuckle as he hands you the letter.>",
},
[8368] = {
["o"] = "Bring 3 Warsong Marks of Honor to a Horde Warbringer outside the battlegrounds.",
["d"] = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, N!  Come back to me with proof of serving the Horde in a worthy manner!",
},
[92473] = {
["o"] = "Collect 6 Scrawny Ursera Claws from Scrawny Ursera in Thendal Grove.",
["d"] = "The ursera den to the southwest is rapidly becoming a problem. Just last week the rangers had to kill an adolescent ursera who wandered too close to the village and attempted to attack a boy playing near the base of the elder tree in the center of the village.\r\n\r\nWe were fortunate that the boy escaped with his life. Hunger and desperation makes these beasts too dangerous to be left unchecked. Go south and put the scrawniest among the ursera down. Bring me their claws as proof when it is done.",
},
[93318] = {
["o"] = "Kill Vulgara the Insatiable in the Shen'dar Highlands and bring her head to Danarii Bellowveil.",
["d"] = "By order of Constable Aonda of the Peacekeepers, a bounty is hereby placed upon the scourge of the highlands, Vulgara the Insatiable. Last spotted on a hilltop rise just southwest of Shen'dar Village, the winged vuldren terror is highly dangerous and should be approached with caution.\r\n\r\nDeliver the beast's head to Danarii Bellowveil to receive your reward.",
},
[91294] = {
["o"] = "Speak to the residents of Bandarion Keep.",
["d"] = "Now that the immediate threat of the murloc attacks is under control, I'd encourage you to show yourself around our stronghold. It isn't much yet, but it's home.\r\n\r\nWhen you are done exploring, seek out Danitha Morr, our leader. She can help you get settled in.\r\n\r\nI'm very glad to have met you, N. May the light be your guide.",
},
[94896] = {
["o"] = "Collect 8 Abandoned Belongings from the ruins of Ban'aethal.",
["d"] = "You look like a capable adventurer. Do you happen to be headed towards Shadowgale Forest? Ban'aethal lies deep in the forest; that's where we're all from.\r\n\r\n<Ealaane gestures to the other refugees.>\r\n\r\nWe've recently had to evacuate Ban'aethal, as it began to fall into the sky. It was sudden and in the middle of the night. If you are headed that way, would you please look for any belongings left behind? The forest and village are far too dangerous for us to return to now.",
},
[1061] = {
["o"] = "Speak with Seereth Stonebreak in the Stonetalon Mountains.",
["d"] = "The spirits of the Stonetalon Mountains are angered, for goblins and their servants are plundering and burning the land.  So the land has cried out, and those who listen for such things... have heard.\n\nSeereth Stonebreak, a promising shaman of the Horde, was sent to Stonetalon.  She reports massive deforestation at the hands of the goblins, and requests aid.\n\nMeet Seereth in Stonetalon.  To reach her, follow the road west of the Barrens' Crossroads.  She is camped near the Greatwood Vale.",
},
[94434] = {
["o"] = "Bring 10 Linen Cloth to Tanis Alderwood in the Undercity.",
["d"] = "Wait, you want to... help? Why would a paladin want to help a beggar like me?\r\n\r\nWell, I suppose that you could be of some assistance. \r\n\r\nIt's my wife you see. She, well... she's falling apart. I mean that literally. The apothecaries can stitch her back together right as rain, but they are about the Dark Lady's business and none are available to help. If you could perhaps bring me some fresh cloth then I could at least make her a wrapping to hold her together while we wait for the apothecaries.",
},
[97558] = {
["o"] = "Bring Shelene Rhobart 8 Duskbat Wing Membranes, 6 Darkhound Hides and 3 Vile Fin Murloc Skin.",
["d"] = "One part of undeath no one mentions is what happens when we are injured. How does the skin of an undead heal itself?\r\n\r\nWell, it doesn't.\r\n\r\nOurs is a cursed life, N. We must take from the living to further our own existence.\r\n\r\nWhen we sustain an injury, we must replace our skin which usually means animal hides. Since different hide thicknesses are better for different places on our bodies a variety is key!\r\n\r\nBring me wing membranes of a duskbat, hides from a darkhound and skin of a Vile Fin murloc.",
},
[427] = {
["o"] = "Executor Zygand of Brill wants you to kill 10 Scarlet Warriors.",
["d"] = "The documents Executor Arren provided are just the break we needed in our battle with the wretched Scarlet Crusade.  We now know their exact locations throughout Tirisfal Glades.\n\nBut the Deathguard has larger concerns.  The Lich King's army grows in number each night.  We need someone with \"initiative\" like yourself to drive the Scarlet Crusade to the grave.\n\nProve to me you are capable of serving The Dark Lady by travelling west to the tower past the Solliden Farmstead and slay 10 Scarlet Warriors.",
},
[99152] = {
["o"] = "Collect 6 Faintly Glowing Bones for Hilda the Breaker.",
["d"] = "While the Tarnished in Shadowvale to the southwest are definitely a problem, we cannot allow the cellars below the town to fester into a full-blown Scourge uprising on Bandarion Keep.\r\n\r\nI need to get these trainees up to snuff in case that happens. You, however, are going to receive what I like to call a crash course.\r\n\r\nTravel beneath Shadowvale and retrieve some of their wretched bones so we can study them further. I need ones that still retain some of the initial reanimation magic--that's glowing ones.",
},
[93319] = {
["o"] = "Collect 10 Pilfered Windstones from the Highlands Bandits in the Shen'dar Highlands.",
["d"] = "We are relying on windstones more and more for day-to-day living here on Zephras so we try and maintain a cache of them in reserve for emergencies. Lately I've noticed some go missing from our stores.\r\n\r\nWe've found windstones on bandits we've captured recently, and I suspect they are behind our shortages.\r\n\r\nIf you find yourself near the bandit cave to the north, mind knocking a few heads together and reclaiming some of our pilfered windstones for me?",
},
[94897] = {
["o"] = "Find Resaan in the Ruins of Ban'aethal.",
["d"] = "If you are traveling to Ban'aethal, I have a selfish request. My love, Resaan... I believe is no longer a part of this world. He had tried to go back to get supplies even though I begged him to stay. It has been over a week already and I fear the worst.\r\n\r\nPlease, if you find him, bring him home. If he has perished then I beg you to please bring me his heirloom.",
},
[94435] = {
["o"] = "Return to Danitha Morr at Bandarion Keep.",
["d"] = "I don't know why you'd go out of your way to help me, but I appreciate it. If someone sent you my way, tell them I appreciate them too. You'll always have a friend in Tanis Alderwood, paladin.",
},
[92682] = {
["o"] = "Gather 10 Ripe Stormapples and slay 5 Hungry Bandits at the Windfield Orchard.",
["d"] = "Oh, so you've got more courage than sense, then? Fine, I won't argue.\r\n\r\nFerauu and his goons aren't due to pick up their take of the harvest just yet, so I'm going to put you to work for your meals until they arrive.\r\n\r\nHead outside and gather today's batch of stormapples for me. Oh, and the bandits lurking around the stormapple trees... They think they are sneaky. They aren't. Kill them for me. \r\n\r\nLet's see what you've got in a fight.",
},
[92698] = {
["o"] = "Speak with Aamelia Windfield about the Malfunctioning Cyclone Construct.",
["d"] = "<You lean in close to try and hear the words coming from beneath the giant construct's armor plates.>\r\n\r\n...Function error...\r\n\r\n...Question...\r\n\r\n...What is....\r\n\r\n...Function...\r\n\r\n<These fragmented words and phrases seem to just repeat. Maybe someone nearby knows more about this construct?>",
},
[886] = {
["o"] = "Speak with Tonga Runetotem at the Crossroads.",
["d"] = "The druids of Thunder Bluff sense a strange power leaking into the Barrens, east of Mulgore.\n\nTonga Runetotem was sent to discover the source of this power, but we fear he will need aid.\n\nTravel to the Barrens and speak with Tonga.  He will be at the Crossroads.  To reach there, take the road east out of Bloodhoof village.  Enter the Barrens, then turn north when the road forks.  Continue north and  you will find the Crossroads.\n\nAnd do not leave the road, N, for the Barrens is a harsh land.",
},
[95328] = {
["o"] = "Deliver Whispering Horror Residue to Father Lankester in the War Quarter of Undercity.",
["d"] = "Against your better judgement you scrape up and collect the squirming remains of the beast. Someone in Undercity might have a use for them.",
},
[492] = {
["o"] = "Bring Johaan's Special Drink to the Captured Mountaineer.",
["d"] = "According to the Deathguard, another one of those foolish Dwarven Mountaineers has just been captured.  The Deathguard likes to use the cellar of the Gallows End Tavern as a holding cell until prisoners can be \"properly\" dealt with.\n\nWhy don't you go see how the Captured Mountaineer enjoys this special drink I made for him?  It contains a subtle hint of what The Dark Lady has planned for the rest of Azeroth.",
},
[93320] = {
["o"] = "Report to Yorana Windyreed at the eastern watchtower in the Gustberry Lowlands.",
["d"] = "I've just received word that the cult is attacking the pylon watchtower just outside of town! I've sent the few extra peacekeepers we have here to try and break through the enemy back line to relieve the defenders, but any additional help could mean the difference between our people there living or dying.\r\n\r\nPlease leave immediately for the east watchtower and provide whatever aid you can.\r\n\r\nMy lieutenant Yorana Windyreed led the relief force. If she still lives she can tell you how best to help.",
},
[94436] = {
["o"] = "Speak with Deathguard Billmuth at Bandarion Keep.\r\n\r\nShould you misplace your Symbol of Life, return to Danitha Morr for a replacement.",
["d"] = "It's time to demonstrate your ability to channel one of the light's greatest gifts.\r\n\r\nThe item I just gave you is called the Symbol of Life. Take care, as it may cause you some discomfort to handle a talisman of the light such as this. The light may be anathema to the force that created us, but it is still our guide and ally. The pain reminds us of this.\r\n\r\nGo see Deathguard Billmuth downstairs. He just arrived and he has petitioned us for aid. Show him and the Forsaken what a true paladin can do.",
},
[365] = {
["o"] = "Steal 10 pumpkins from the farm to the west, just north of Deathknell and take them to Apothecary Johaan in Brill.",
["d"] = "What have we here?  You look like a fledgling paladin.  If you hope to prove yourself to The Dark Lady, you need to learn the ways of The Forsaken.\n\nTo the west you'll find a farm.  Humans infest the land like mold on a rotting corpse.  And worse yet, the Scarlet Crusade patrols nearby from their tower.  Teach those scum a lesson and steal 10 of their precious pumpkins.\n\nOnce you have 10, take them to Apothecary Johaan in Brill.",
},
[92683] = {
["o"] = "Gather 5 Flutterfly Dust from the Flutterflies around the Gustberry Lowlands.",
["d"] = "I'm sure you've noticed the giant flutterflies out in the outer fields near the orchard? They are pleasant to look at, but they also have other benefits; namely their wing dust. It can be a mess, but if you can gather it up in large amounts, it has useful household applications.\r\n\r\nTake this Flutterfly Swatter and give the big bugs a good swat for me. They'll usually just get scared and flee, but sometimes they'll take some offense. Either way, they'll give their rumps a shake and drop a pile of dust.",
},
[94484] = {
["o"] = "Find and speak with Elegael Thornpaw in the northeastern part of Shadowgale Forest.",
["d"] = "A moment if you will, N. Are you headed towards Shadowgale Forest? There is a druid conclave there in a cave to the northeast. I have been waiting on word from them but their correspondence is long overdue.\r\n\r\nWith Ban'aethall in ruins and all the unrest lately I worry something dire may have happened. Please, if you are able, go seek out Elegael Thornpaw and put my mind at ease.",
},
[92460] = {
["o"] = "Speak with Rorian the Dayseeker in Thendal Grove.",
["d"] = "Look at you, bright eyed and ready for adventure! We need all the help we can get here in Thendal Village and your arrival is most welcome. I imagine you are brimming with nerves for what is to come. After all, you only get to come of age once in a lifetime.\r\n\r\nGo, seek out our village leader Rorian the Dayseeker at the entrance to the greatfather tree just west of here. He will get you started on your journey.",
},
[94006] = {
["o"] = "Speak with Urs'endris near the falls northeast of Valanaar.",
["d"] = "Greetings, N. You have progressed in your druidic studies far enough that I think it is time for you to meet one of the great spirits that reside here on Zephras. Urs'endris is a wise and noble spirit, who has taught druids how to take on the ursera shape for generations. Unfortunately his domain has begun to wither and fall into the sky like many other areas of Zephras.\r\n\r\nTo find him, travel northeast near the waterfall in the shadow of the Shrine of Akir. He should be able to instruct you further.",
},
[445] = {
["o"] = "Take Apothecary Johaan's findings to Apothecary Renferrel in Silverpine Forest.",
["d"] = "Time is a luxury that is not afforded to those of us under the employ of Lady Sylvanas.  Surely you know this by now.\n\nAs a member of the Royal Apothecary Society it is my duty to share my knowledge with my colleagues so that our collective efforts might one day provide The Dark Lady with the New Plague she so badly desires.\n\nTake these findings to Apothecary Renferrel who is stationed at The Sepulcher in Silverpine Forest.  Follow the roads to the south from Brill.  From the Undercity go southwest.",
},
[97959] = {
["o"] = "Speak with Brom Killian in Undercity to learn to craft a camping item for your profession once you have shown proficiency in your skill.",
["d"] = "Mining isn't the most glamorous, but it's good honest work and a fine profession for you to explore.\r\n\r\nI reckon I know someone that can teach you how to craft a Lodestone for your camp. Build one of these and everyone who wants to swing a sword will be eager to gather round your fire and soak up the extra \"oomph\" it can provide to increase their combat prowess.",
},
[94638] = {
["o"] = "Find and kill Ur'endra in the Shen'dar Highlands.",
["d"] = "You have come to me in hopes of learning to take a shape of strength. I have a task for you, though it lies heavy on my heart.\r\n\r\nMy mate, Ur'endra, has lost herself to madness and has begun to attack her own kin. Without the magic of the winds, many creatures have begun to lose themselves... Ur'endra included. She makes her lair in a cave to the west of here, in the bluffs along the border between the Shen'dar Highlands and the Gustberry Lowlands.\r\n\r\nEnd her suffering and I shall grant you my blessing.",
},
[93927] = {
["o"] = "Collect the note you found near the dead peacekeeper and read it to determine your next steps.",
["d"] = "<As you inspect the body of the dead peacekeeper, a bloody note falls free of his hands. Picking it up and reading it may give you a clue as to how to proceed from here.>",
},
[366] = {
["o"] = "Return Gunther's Spellbook to him, on the island of Gunther's Retreat.",
["d"] = "Long ago Gunther and I, along with the now Scourge Necromancer Thule Ravenclaw, were friends and students within the Kirin Tor - a society of mages in Dalaran.\n\nGunther and I both fell to the Plague, but I thought he either remained dead, or was raised into the ranks of the Lich King.  It is good to know he is free.\n\nWe must have him.  I have placed a spell on his book that, when he sees it, will show him that I too am free of the Lich King.  After knowing this, it is my hope that he will join us.",
},
[92684] = {
["o"] = "Gather 7 Lowlands Galestrider Tenderloins from the Ornery Galestriders found throughout the Gustberry Lowlands.",
["d"] = "As if the harvest wasn't light enough this year already, the galestriders in the area have been getting into the orchard and stealing my stormapples. Think you can head out to the fields and cull them for me?\r\n\r\nTake care though stranger, these lowlands galestriders are bigger and angrier than the highlands variety. Watch yourself. A well-timed kick is all it takes to put you down for good if you aren't paying attention.\r\n\r\nBring me some of their meat and I can make us a hot meal with it as well.",
},
[92700] = {
["o"] = "Find Ayessa Dawnsinger in Valanaar.",
["d"] = "Now that you've arrived in Valanaar, you'll likely want to check in with the other members of the Windshapers here. The current Grand Skyseer and her people operate out of the lodge near the center of Valanaar.\r\n\r\nYou should also be aware, the Windshapers and High Order don't get along very well in these parts. Be careful and give the High Order a good, wide berth. We've got enough to worry about with the cult, I won't tolerate faction violence in the streets of Valanaar.",
},
[92461] = {
["o"] = "Slay 8 Vuldren Juveniles in Thendal Grove.",
["d"] = "We live in times of great uncertainty for our people. We face unprecedented challenges that may require bold solutions, but we also must contend with the ordinary and mundane here in Thendal Grove. Take, for example, the recent unsustainable rise in the vuldren population.\r\n\r\nThe vuldren are a vital part of our ecosystem. However, imbalances must be corrected to maintain the delicate harmony that all creatures in Thendal Grove share.\r\n\r\nHead east and cull some of the vuldren there.",
},
[94007] = {
["o"] = "Report to Quel'ana Quickgale in Valanaar.",
["d"] = "Now that you've gained a level of comfort in the wilds of the highlands, I believe it is time for you to seek your very own animal companion.\r\n\r\nGo to the port of Valanaar to the southeast, and speak with Quel'ana Quickgale there. He will instruct you in the art of beast taming.",
},
[5761] = {
["o"] = "Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.",
["d"] = "The primary task set upon me by our great Warchief is to root out the creatures responsible for infesting our lord's great city with demonic influence. The Burning Blade is one threat, but there are others; the Searing Blade for instance, who make their home in Ragefire Chasm, secretly attempting to subvert innocent members of the Horde.\n\nIf they are to be stopped, then their leader must be slain--a Felguard named Taragaman the Hungerer.\n\nKill him, and his heart will appease Thrall, of this I'm sure.",
},
[95314] = {
["o"] = "Collect 8 Bottles of Whispering Elixir from Shadowvale, then return to Carolai Anise in Brill.",
["d"] = "Before the Scourge invasion, the reclusive village of Shadowvale was known for its Whispering Elixir. Distilled from herbs found only in Tyr's Fall, the elixir was sought by apothecaries, mystics, and poisoners alike even after being banned in the city.\r\n\r\nI've had requests from a number of buyers eager to get their hands on some elixir. Travel to the ruins of Shadowvale deep in the Whispering Forest to the west. I'm prepared to offer significant compensation if you can recover some bottles for me.",
},
[94979] = {
["o"] = "Use the Taming Rod to tame an Ornery Galestrider in the Gustberry Lowlands. \r\nPractice your skills, then return the Taming Rod to Quel'ana Quickgale in Valanaar.",
["d"] = "You've proven you can tame the river's crawler. Now it's time to test your skill on open ground. The plains of Zephras echo with the cries of the galestrider, a proud, winged hunter that runs like the wind.\r\n\r\nTake this Taming Rod and seek one out. Travel to the lowlands and earn its trust.\r\n\r\nShow you're ready for the trials yet to come.",
},
[93958] = {
["o"] = "Speak with Valennia Stormfist inside the inner sanctum at the Shrine of Akir.",
["d"] = "Valennia's forces just breached the inner sanctum. The fighting was thick in there at first, but it's grown... unsettlingly quiet. Go in there and do your best to link up with Valennia and her forces... if any of them are left.\r\n\r\nI'll stay here and watch your back.",
},
[91282] = {
["o"] = "Find the fortress of Bandarion Keep and report to Breton Samuels there.",
["d"] = "It is encouraging to see my newly risen brothers and sisters thrive as you have. It is only through community and shared faith that we can truly realize our full potential however, and to that end we've begun to form a new paladin order right here in Tirisfal. \r\n\r\nIf you wish to learn more, you should visit our monastery on the edge of the Whispering Woods. It is called Bandarion Keep. It's on the bluffs just northwest of the Solliden Farmstead, and should be hard to miss.",
},
[92483] = {
["o"] = "Read the Simple Note then speak with Akeri Duskblade within the watchtower in Thendal Grove.",
["d"] = "While you were away dealing with our vuldren problem, our resident rogue trainer--Akeri Duskblade--has requested to speak with you. He left this note, so read that first, then seek him out inside the watchtower, here in the village.\r\n\r\nHe's a shady fellow, but then again, so are you. I think you'll get along well.",
},
[97971] = {
["o"] = "Speak with Mendalass Tattermend in Shen'dar Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.",
["d"] = "Being able to skillfully harvest the skins and hides of fallen beasts is one of the more valuable skills an adventurer can possess.\r\n\r\nI reckon I know someone that can teach you how to craft a Camp Chair for your camp. Sometimes it's important to just take a load off, and you can use some of those hides you've gathered to make a comfy chair to sit in. A bit of relaxation can help ensure that you are at your peak condition and can strike where it counts the next time you find yourself in a dust-up.",
},
[97257] = {
["o"] = "Wait for Olariaan to begin the ritual at the Brazier of Offering and follow his instructions.\r\n\r\nYou must deliver the Eternal Flame to Valanaar before the timer runs out.",
["d"] = "Now we will perform the ritual. \r\n\r\nI will place the materials onto the altar and call forth the spirits of flame. If the offering is accepted, they will appear and light the Eternal Flame. You will then hold your torch forth and capture the flame.\r\n\r\nCarry the lit torch to Valanaar and place it in the Brazier of Eternal Flames. You must do so quickly, for the flames of the Firelands are quick to dissipate here in Skywall.",
},
[99156] = {
["o"] = "Bring Riptear's Heart to Deathguard Linnea.",
["d"] = "Damn it all! A new report came in while you were on patrol. There has been a sighting of a rogue abomination wandering Eastern Tirisfal Glades, near Venomweb Vale.\r\n\r\nSomething is wrong. Abominations don't just slip through the Bulwark unnoticed.\r\n\r\nKeep this matter on a strictly need-to-know basis. That said, such a creature will not fall easily; you will need allies if you wish to be more than its next meal.\r\n\r\nSee this through, and you will be duly rewarded. Bring me its heart as proof of the deed.",
},
[93949] = {
["o"] = "Kill Skyhoppers in Valanaar until you've eliminated 8 Enchanted Skyhoppers.",
["d"] = "We've been bugged.\r\n\r\nIt's skyhopper season in the lowlands, which means the pests are everywhere. One of the High Order mages reported that one of the insects that they killed had an enchantment of some kind placed upon it. When we inspected it closely it seems to be some sort of listening spell.\r\n\r\nWe suspect that the cult is using these enchanted insects as spies. Go and exterminate them for us. You won't be able to tell which are enchanted by looking at them, so you'll just have to kill them all.",
},
[94438] = {
["o"] = "Take the Symbol of Life and use it to resurrect Deathguard Falgan at Venomweb Vale. \r\n\r\nShould you misplace your Symbol of Life, return to Danitha Morr for a replacement.",
["d"] = "Falgan and I were sent on a mission to scout out scarlet activity in Venomweb Vale. We managed to sneak close enough to one of their camps to hear about new orders involving an attack on Brill. Before we could decide what to do next, I stepped on a twig and the noise alerted them to us.\r\n\r\nFalgan yelled at me to run, so I ran. By the time I realized he wasn't with me, I was halfway to Brill. That brave idiot probably stayed behind to hold them off for me.\r\n\r\nPlease, find my friend and help him if you can.",
},
[98024] = {
["o"] = "Report To Thork at The Crossroads in The Barrens.",
["d"] = "After journeying here from the elemental plane, the problems our lands face may seem small. Rest assured, the dangers the horde faces are very real, and you will grow formidable should you survive your service.\r\n\r\nIf you'd like to get started doing some good in our world, travel southwest to the vast lands known as the Barrens. There is a settlement there known as the Crossroads. The proud citizens there are ever in need of aid.\r\n\r\nGo with honor, adventurer!",
},
[92685] = {
["o"] = "Loot 7 Blood-Stained Bandit Masks from Highwayman Bandits in the Gustberry Lowlands.",
["d"] = "The bandits have camps all over and there's a small one in the hills just north of here. Head up there and start cracking skulls. If we can catch them off guard and take them out before they come for us, we might just even the odds enough to stand a chance.\r\n\r\nBring me their masks. The bloodier the better.",
},
[94486] = {
["o"] = "Collect 20 feathers from the Shadowgale Shrieklings in Shadowgale Forest.",
["d"] = "The other ingredient I need for the poultice is feathers from the Shadowgale shrieklings that roam this forest. In their juvenile form, the shrieklings have insulative feathers which would be ideal to put over the moss. These feathers will prevent the antiseptic sap from drying out and will provide at least some protection against the elements.\r\n\r\nBe warned, the shrieklings are normally docile but they have been incredibly hostile of late. Their large talons can easily disembowel you if you aren't careful.",
},
[92462] = {
["o"] = "Slay 8 Pesky Cirrusflies in Thendal Grove.",
["d"] = "One of our rangers recently reported an infestation of cirrusflies here in Thendal Grove. \r\n\r\nCirrusflies can be dangerous if the swarm is allowed to grow too large, so please head to the eastern end of the Grove and exterminate as many as you can.",
},
[398] = {
["o"] = "Kill Maggot Eye and return to Executor Zygand in Brill with his paw for a reward.",
["d"] = "Wanted: Maggot Eye!\n\nA foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken.  This despicable villain has been stealing corpses for use by the Lich King's army.  Maggot Eye was last seen pillaging the lands near Garren's Haunt to the north of Brill.\n\nThe town of Brill hereby offers a reward to the capable soul who can carry out the execution.  Show Executor Zygand the villain's paw once the deed is done.\n\nMercy is for the weak.",
},
[92642] = {
["o"] = "Slay 4 Al'Aketh Healers and 8 Al'Aketh Brawlers in the Gustberry Lowlands.",
["d"] = "Valennia only sent one person to help repel a full-scale assault... by the winds.\r\n\r\nYou don't look like much but I'll take what I can get. We need to inflict as much damage as possible to stop this soon. My people can't hold out much longer.\r\n\r\nGo down the hill and disrupt their logistics. Their healers are keeping the attackers coming, if we take them out we might be able to rally and push them back. Any other cultists you kill while you are out there are helpful as well.",
},
[92881] = {
["o"] = "Speak with Talaanis Shadowsong in Valanaar.",
["d"] = "The attacks on both the western and eastern watchtowers are not a coincidence. Based on what you told us about what occurred at the western watchtower with that skypriest, our best guess is that the cult is trying to do something to the anchor pylons.\r\n\r\nPlease speak with High Elder Shadowsong. He will tell you about a lead that could prove to be promising.",
},
[93036] = {
["o"] = "Speak with Sania Silverstream in Shen'dar Village.",
["d"] = "You may or may not be aware of this, but Sania Silverstream over there is a \"missionary\" for the Al'Aketh. They like to play at being a normal religious order and send non-threatening emissaries around to recruit. We've tolerated Sania so far to avoid direct conflict with the cult, but it's obvious the illusion of peace won't last much longer.\r\n\r\nYou are new here and unknown to most, so I'd like to see if you can use Sania to get close to the cult and find out what their plans are for the village.",
},
[97243] = {
["o"] = "Bring the Torch of Dormant Flame to Olariaan Swiftburn at the Shrine of Flames in the Gustberry Lowlands.",
["d"] = "Even though we are in the realm of Skywall, this is still the elemental plane. The spirits of all four elements speak to us, if we deign to listen. One among us Windshapers is in particular attunement with the element of fire. A shen'dorei by the name of Olariaan Swiftburn.\r\n\r\nBring this to him at the Shrine of Flames in the Gustberry Lowlands. You'll find it tucked away along the edge of the island, west of Valanaar.",
},
[96638] = {
["o"] = "Speak to Raan Wildwind near Shen'dar Village.",
["d"] = "More and more adventurers like yourself have been seeking glory and fortune outside of the safety of Thendal Grove. There's one such adventurer who has made a camp outside of Shen'dar Village, along the road leading southwest out of Thendal Grove.\r\n\r\nSeek him out and see what you can learn from him that may help you in your own travels.",
},
[93159] = {
["o"] = "Speak with the Strange Hermit in the Shadowgale Forest and learn more about him.",
["d"] = "Uh, um... h-hello, I mean to say, hi! Greetings, even! I'm sorry... it's um, been so long since I've actually spoken to another person. I'm afraid I'm a bit rusty at this.\r\n\r\n<The strange hooded figure shifts uncomfortably before you.>\r\n\r\nSo er, um... how is your day going?",
},
[92463] = {
["o"] = "Destroy the Cirrusfly Queen in Thendal Grove.",
["d"] = "If the forest is as thick with these insects as it sounds, simply killing the workers won't be enough.\r\n\r\nGo deeper into the forest and find the queen. She'll be close to the hive and surrounded by bigger and more aggressive soldiers, so be careful.\r\n\r\nPut her down and return here when it's done. That'll be one less problem to think about around here.",
},
[92871] = {
["o"] = "Report to Valennia Stormfist and let her know that the Windshapers are with them in their fight against the Al'Aketh.",
["d"] = "Valennia Stormfist and her peacekeepers have ever been the protectors of Zephras, and we've done our best to lend aid where we can. There are rumors of larger-scale cult movements around the island, and they are clearly gearing up for something.\r\n\r\nReport to Valennia and reiterate to her that the Windshapers offer their full support in Valanaar's efforts against the Al'Aketh, should the need arise.",
},
[93735] = {
["o"] = "Find Riaani Nightwind on the west side of Valanaar.",
["d"] = "Historically, the Windshapers have seen to the tending of the magical instruments and devices that were gifted to us by the spirits of the wind. This includes the myriad of magical constructs around the island. Since the spirits left us, only a scant few of these are still functional.\r\n\r\nOne of the few remaining working constructs in Valanaar has become damaged. One of our artisans was dispatched to help, but he may be in need of aid. Travel to the west end of the city and offer any assistance you can.",
},
[92474] = {
["o"] = "Jump from the top of the watchtower in Thendal Grove and use your Walk on Air ability to slow your fall.",
["d"] = "Well hello there, N! Want to play a game?\r\n\r\nAll you've got to do is step up on that ledge... then jump! Use your innate ability to walk on the air to slow your fall and see how far forward you can float.\r\n\r\nThe rules are made up and the points don't matter, but you get bonus points if you can land right in front of Rorian the Dayseeker and startle him! He won't like it but I'll certainly get a good laugh if you can get him all worked up! Hah!",
},
[97244] = {
["o"] = "Slay Skypriest Faladiel in the Gustberry Lowlands and collect Faladiel's Heart.",
["d"] = "There is an Al'Aketh Skypriest called Faladiel. He was once a caller of the flame and a stalwart Windshaper. Like so many Al'Aketh, he mortgaged his loyalty for power and his hands are now stained with the blood of his former brothers and sisters.\r\n\r\nYou will find Skypriest Faladiel at the farm to the northeast past Valanaar, just to the south of the Shrine of Akir. Kill the betrayer. Bring me his heart. It is a gruesome task, but it is needed for the ritual we are to perform.",
},
[368] = {
["o"] = "Apothecary Johaan of the town of Brill needs 5 Vile Fin Scales from Murlocs in Tirisfal Glades.",
["d"] = "While you were collecting samples for me, my experiments led me to realize that more reagents will be required for this new disease to spread properly. Poisoning some hapless victim is child's play. Plaguing an entire world proves to be a bit more complicated.\n\nI will need 5 Vile Fin Scales from Murlocs in the vicinity.  You will find the creatures along the coast to the north or to the west.",
},
[92514] = {
["o"] = "Speak with Illaya Amberwind and Coriella Calmbreeze in Shen'dar Village.",
["d"] = "You've got that \"Windshaper\" air about you. Something about how I can feel a tiny bit of static on my skin when near someone spirit-touched that gives it away. Before I properly put you to work around here, you should check in with our resident Windshaper elder, Illaya Amberwind. She's just outside, near the center of town.\r\n\r\nOh, and check in with Coriella Calmbreeze as well, she runs the local inn and can provide lodging and supplies, should you need them.",
},
[94487] = {
["o"] = "Collect 10 Bloodied Heirlooms from Al'Aketh Footsoldiers and Al'Aketh Stormchasers in the Shadowgale Forest.",
["d"] = "The Al'Aketh Cultists ambushed us with no warning, though their motives remain a mystery to me. I knew these cultists had clouds between their ears, but I never imagined they would upset the delicate balance here on Zephras with such brutality. Go, slay as many as you can and take their heirlooms if they wear any.\r\n\r\n<Elegael spits.>\r\n\r\nThese storm-cursed cultists don't deserve to be called shen'dorei. The beasts of the forest can have their bodies. Their ashes don't deserve the winds.",
},
[93738] = {
["o"] = "Report back to Ayessa Dawnsinger in Valanaar.",
["d"] = "Brightwish, eh? So the High Order wanted to remove these components for some reason. But why though?\r\n\r\nThe High Order has always been meddlesome, constantly wanting to experiment with the wind spirits' magic. They are too bold by a mile, and we've strictly forbidden them from meddling with knowledge under Windshaper purview, but lately they've been testing our patience.\r\n\r\nI think you should report what you've learned back to Ayessa Dawnsinger. She can instruct you further on what to do.",
},
[411] = {
["o"] = "Bring the Nether Gem to Bethor Iceshard in the Undercity.",
["d"] = "Take this Nether Gem to my old comrade Bethor.  It will let us communicate ... and I have much to tell him.",
},
[426] = {
["o"] = "Gather 5 Notched Ribs and 3 Blackened Skulls, then return to Deathguard Dillinger in Brill.",
["d"] = "The Scourge are trying to form a base at the Agamand Mills.  If they do, then they can stage further attacks within Tirisfal.\n\nThe orders have been given.  The Scourge in the Mills must be destroyed.\n\nGo to the Mills.  Collect Notched Ribs from Rattlecage and Cracked Skull Soldiers, and Blackened Skulls from Darkeye Bonecasters.\n\nTo get to the Mills, follow the road west.  After crossing the bridge, take the next fork north then keep going north.  When you see windmills, the battle will begin.",
},
[93746] = {
["o"] = "Confront Belathaan Brightwish along the road to the Shrine of Akir.",
["d"] = "The High Order has been warned of the consequences of meddling with the Windshaper's affairs. I think we need to make an example out of Belathaan and send him back to the High Order with a few bruises and a healthy respect for the boundaries we set.\r\n\r\nBelathaan was seen leaving town, traveling north towards the Shrine of Akir. I don't know why he was going there, but confronting him alone on the road is the safest option. Find him, and put a bit of fear into his heart.",
},
[97953] = {
["o"] = "Speak with Vance Undergloom in Brill to learn to craft a camping item for your profession once you have shown proficiency in your skill.",
["d"] = "Enchanters make everything better and are always welcome at any camp out in the wilds.\r\n\r\nI reckon I know someone that can teach you how to craft an Enchanted Lute for your camp. It's so important to find entertainment during your downtime, and this bit of magic can help ensure you are ready to weather all sorts of challenges when you hit the old dusty trail once again.",
},
[94488] = {
["o"] = "Kill Commander Haalien and bring his head to Elegael Thornpaw in the Shadowgale Forest.",
["d"] = "The reason for cultists' presence here still baffles me, but I smell a familiar scent over the bloodshed.\r\n\r\nOne of our circle druids, Haalien, disappeared months back. It appears he's thrown his sorry hide in with the cultists.\r\n\r\nShow him what happens when he spills the blood of his kin! Take his head and return it to me.",
},
[371] = {
["o"] = "Executor Zygand in Brill has commissioned you to slay Captain Vachon and 5 Scarlet Friars.",
["d"] = "We are still at war and the Scarlet Crusade grows in strength.  The report Executor Arren sent me indicates Scarlet Crusaders have been raiding from the ruined tower in southeastern Tirisfal near the Balnir Farmstead under the command of Captain Vachon.\n\nKill Vachon along with 5 Scarlet Friars. It should prove to be a devastating blow to the Crusade!",
},
[92553] = {
["o"] = "Collect 3 Small Eggs and 8 Strider Meat from creatures found throughout the Shen'dar Highlands.",
["d"] = "Up for a bit of work? I could use a bit of muscle from a strong adventuring-type such as yourself. With how dangerous things are getting around here, no one's had much time to hunt or forage of late, and I need someone to get out there and source me fresh eggs and strider meat to keep this village fed.\r\n\r\nI'd be happy to teach you one of my famous recipes if you can bring me what I need. What do you say?",
},
[91316] = {
["o"] = "Collect 12 pieces of Sturdy Lumber from Shadowvale in Tirisfal Glades.",
["d"] = "This far from the Undercity, logistics are challenging and we have a dire shortage of building materials needed to help restore this fortress. I'd like your help with that.\r\n\r\nThe ruined village of Shadowvale can be found in the Whispering Forest, just southwest of here. One of the buildings has an old root cellar used to store all sorts of things. There are likely to be usable materials down there. Scavenge what you can and return to us.",
},
[95349] = {
["o"] = "Take the skycutter ship from Zephras Isle to Mulgore and speak with Alaana Stormwalker when you arrive.",
["d"] = "The recent events with the cult have delayed my plans to travel to Azeroth and I must remain here in Valanaar for a time. You and a handful of other Windshapers will be our vanguard instead. Alaana Stormwalker will be waiting to receive our Windshapers upon arrival in Mulgore, and I'd encourage you to explore Azeroth while we finish our business here. We will join you soon.\r\n\r\nWhen you are ready, please proceed to the dock just outside this lodge and board the skycutter ship there. \r\n\r\nBanu-Alah, N.",
},
[94440] = {
["o"] = "Retrieve the Scarlet Crusade Attack Plans from the Scarlet Crusaders at Venomweb Vale, and return to Deathguard Billmuth at Bandarion Keep.",
["d"] = "These Scarlet Crusaders often carry satchels with their deployment orders. We know an attack is coming, but if we can recover their orders, we can warn the rest of the Deathguard and prepare an ambush. \r\n\r\nYou are clearly an impressive paladin. Kill these scarlet animals and retrieve a copy of their orders and bring them back to Deathguard Billmuth. He'll take it from there.",
},
[96895] = {
["o"] = "Find the Argent Dawn member near the entrance to the Undercity.",
["d"] = "Not sure if you heard, but two emissaries of the Argent Dawn just passed through here. I don't mind the Argent Dawn, but I don't like them poking around Tirisfal unsupervised either. They were both Forsaken... but that doesn't make me any less nervous.\r\n\r\nOne of them just passed by here, headed southeast. There's a group of scourge cultists snooping around the outskirts of the city in that direction. If those two heard about them, there's no doubt that would have caught their attention.",
},
[93165] = {
["o"] = "Collect 5 Al'Aketh Cultist's Ears from the Al'Aketh cultists in Shadowgale Forest, the Shrine of Akir, or Gustberry Lowlands.",
["d"] = "The Al'Aketh have visited great tragedy upon our enclave, and blood must be repaid with blood.\r\n\r\nI have an offer for you, stranger. Should you find conflict with these accursed cultists, bring me the ears of those you kill. I will reward you for each that you return with in both coin and, in time, access to the Nightclaw's secrets should you prove yourself to be a true friend.",
},
[369] = {
["o"] = "Apothecary Johaan in the town of Brill wants you to bring him 4 samples of venom from a Vicious Night Web Spider.",
["d"] = "While you were out gathering, I uncovered some old text in one of my tomes that indicates that an ancient plague wiped out thousands of innocent victims.  Later it was discovered that the deadly agent in the plague was preserved through the venom of Night Web Spiders.\n\nBring me some venom from a Vicious Night Web Spider to complete this experiment.  I want to see if the contagious element from the venom will work with my new concoction.  Rumor has it the spiders can be found in Eastern Tirisfal Glades.",
},
[97485] = {
["o"] = "Purchase a Bundle of Herbs from Nida the herbalist, a Bundle of Cedar Twigs from Nata the enchanting supplier, and Sinew Thread from Mahu the leatherworking supplier and Ceremonial Flint and Tinder from Naal the cooking supplier.\r\n\r\nCombine the items and sprinkle the incense off of Hunter's Rise.",
["d"] = "Blessings of An'she, friend.\r\n\r\nWe tauren have a tradition of scattering incense to the winds and I was hoping you'd be interested in honoring this tradition.\r\n\r\nYou will need to craft the incense by purchasing herbs from Nida, cedar from Nata, sinew thread from Mahu in the mid rise, and ceremonial flint and tinder from Naal on the upper rise. Once you have these items, combine them and spread them off the south facing cliff of Hunter's Rise.\r\n\r\nYou will find a mat and incense at the ceremonial site.",
},
[92703] = {
["o"] = "Speak with Alvarion Windfield in Valanaar.",
["d"] = "I guess it doesn't feel quite right to keep calling you stranger after all of this so... thank you, N. \r\n\r\nIf you wouldn't mind and are back out that way, please let Alvarion know what happened here. Also, tell him that once he's up on his feet he needs to bring a windshaper back here to look at that construct for us to make sure it's safe to have around our... our family.\r\n\r\n<Aamelia touches her belly gently.>\r\n\r\nHe doesn't know about this part. Let's just keep that bit between us for now.",
},
[93739] = {
["o"] = "Speak with Nazgrel in Grommash Hold to receive further instructions. Use the instructions received to locate and speak with Vol'jin, Cairne Bloodhoof, and Lady Sylvanas Windrunner.",
["d"] = "Azeroth is a large world, and the territory of the Horde is vast. The Undercity, Orgrimmar, and Thunder Bluff all have very unique people and culture.\r\n\r\nIf you are to be a guest of the Horde here on Azeroth, it would do you good to visit each of our capital cities in turn. Speak with my advisor Nazgrel for directions.",
},
[374] = {
["o"] = "Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill.",
["d"] = "Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them.\n\nVarimathras, lieutenant to The Dark Lady, is seeing to it personally that the scum of Azeroth, the Human race, gets wiped into oblivion. Here in Tirisfal Glades we face a particularly annoying breed of humans: The Scarlet Crusade.\n\nVenture forth and wage an offensive on the Scarlet Crusade, paladin. Bring me back 10 Scarlet Insignia Rings as proof of your loyalty to Varimathras and The Dark Lady.",
},
[96896] = {
["o"] = "Observe the conversation between Danitha Morr and Leonid Barthalomew the Revered.",
["d"] = "Danitha and I fought against the Scourge in the defense of the Undercity when Naxxramas attacked. We lost many good friends that day, including the hero after which this keep was named--Garek Bandarion.\r\n\r\nHe might just have been the first Forsaken to rediscover how to wield the Light as a paladin. I am encouraged to see his legacy and potential live on here with Danitha and her cohort.\r\n\r\nIf only the rest of the Forsaken felt the same way...",
},
[99142] = {
["o"] = "Collect 5 Tomb Weed and deliver them back to Junior Apothecary Holland.",
["d"] = "If you're heading east, towards the Balnir Farmstead, I have more you might do for me. Good help is ever so hard to find these days, as your run-in with Gordo illuminates ever so clearly.\r\n\r\nAs I acquire doom weed I perform some minor alchemical alterations and replant them on that farmstead to cultivate my ultimate creation. I call it tomb weed, and it shall be the herald of my glorious destiny.\r\n\r\nDo keep an eye on the Scourge in the area while you're there. They seem... drawn... to the weed. Curious.",
},
[92528] = {
["o"] = "Look around Falaath Village to learn about the cult's intentions in the Shen'dar Highlands.",
["d"] = "The faithful of Al'Akir grow ever stronger with each eager new recruit like yourself. As you can see, our strength gives form to the storm itself!\r\n\r\nNormally I'd send you straight to Skypriest Aanders for assessment, but he is occupied at present receiving a guest at the inn on the north side of town. Please avoid that place for now. An unshaven recruit like yourself in the presence of such a guest would be inappropriate.\r\n\r\nFor now, just don't get in anyone's way.",
},
[92544] = {
["o"] = "Slay 6 Al'Aketh Brutes, 4 Al'Aketh Neophytes, and Malduko Cloudcrush in Thendal Grove.",
["d"] = "A band of Al'Aketh cult ruffians have taken up residence near the temple ruins just southwest of here, led by a real monster called Malduko Cloudcrush. This rabble has no doubt been dispatched here by High Priestess Lorthuna at the Shrine of Akir to attack travelers and coerce our people into joining the cult.\r\n\r\nI need to stay here at my post to alert travelers leaving the grove of the danger, but I would be grateful if you could do something about those cultists and their leader for me.",
},
[91285] = {
["o"] = "Slay 8 Vile Fin Attackers and 8 Vile Fin Seers and report back to Breton Samuels when it is done.",
["d"] = "Normally we'd show our newcomers a bit more hospitality, but we've got a bit of a murloc problem at the moment.\r\n\r\nA tribe of murlocs used to use the keep as their spawning grounds. They've been a problem since we moved in and kicked them out, but now it's starting to get out of hand. You look like you've seen some action. Do you think you could help us drive back some of these pests? You'll find them lurking in the bluffs along the road to the east, and in the camps around the lake to the west.",
},
[98284] = {
["o"] = "Speak with Nasalanna Windsinger in Shen'dar Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.",
["d"] = "Enchanters make everything better and are always welcome at any camp out in the wilds.\r\n\r\nI reckon I know someone that can teach you how to craft an Enchanted Lute for your camp. It's so important to find entertainment during your downtime, and this bit of magic can help ensure you are ready to weather all sorts of challenges when you hit the old dusty trail once again.",
},
[91317] = {
["o"] = "Slay 8 Tarnished Drudges, 6 Tarnished Zealots, and collect the head of Commander Rudolph Gelhardt in Tirisfal Glades.",
["d"] = "Not all risen paladins have acclimated well to our new existence, as you may have seen yourself already. Some have carried forward their prejudices from life, and continue to visit violence upon their fellow Forsaken.\r\n\r\nAs it stands we are mistrusted by our people who remember well the persecution inflicted by the living in the name of the light, and these attacks do not help. A number of these tarnished have taken up residence at Shadowvale to the southwest. End them and bring me their leader's head.",
},
[962] = {
["o"] = "Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom.",
["d"] = "The Royal Apothecary Society, based in the great Undercity of Lordaeron, has sent me here for a very specific service, N. Perhaps you wish to aid me, and in turn The Dark Lady in our efforts to advance the Forsaken.\n\nRecently I studied a rare specimen of flora named Serpentbloom. I believe in greater quantities this herb has great potential.\n\nUnfortunately Serpentbloom can only be found in the darkest recesses of the Wailing Caverns, a dangerous cave system located in the Barrens.",
},
[92465] = {
["o"] = "Slay 6 Roiling Winds and 7 Al'Aketh Converts in Thendal Grove.",
["d"] = "The Al'Aketh cult is a blight upon this island. These cultists are surely the ones responsible for agitating the simple wind sprites that reside here and turning them violent.\r\n\r\nRegrettably, we'll need to disperse these roiling winds here before they harm someone. We also need to send a clear message to the cult that they are not welcome in the grove.\r\n\r\nWill you lend me your aid, druid?",
},
[92640] = {
["o"] = "Speak with Valennia Stormfist in Valanaar and follow her instructions.",
["d"] = "Since engaging the cult in the open is not viable, our best chance is going to be to use this opportunity to attack the shrine itself. We can take Lorthuna herself off the board before she can finish her part of this scheme.\r\n\r\nIt so happens that Valennia has been preparing a strategy for a potential assault on the Shrine for some time now. The only problem is, we will need help. \r\n\r\nSpeak with Valennia for the details.",
},
[97246] = {
["o"] = "Visit Borstan's Firepit and tell him Thatog wants you to deliver Migi's lunch to him personally.",
["d"] = "My son, Migi, always takes off to play with his friends all day. I tell him to pick up a lunch at Borstan's, but I know he almost never does, because he comes home starving. These kids think their games are more important than their own bodies!\r\n\r\nPlease, stop at Borstan's Firepit and tell him you're there to deliver Migi's lunch. You can almost certainly find Migi behind Grommash Hold with the rest of his friends.\r\n\r\nDuties keep me here during the day and I can't watch over his every meal.",
},
[370] = {
["o"] = "Executor Zygand in Brill wants you to kill Captain Perrine, 3 Scarlet Zealots and 3 Scarlet Missionaries.",
["d"] = "The strategic documents from Executor Arren contain all the details we need to wipe the human infestation from the lands.  According to the information, The Scarlet Crusade has assigned Captain Perrine and a brigade to the ruined tower southwest of Brill.\n\nKill Perrine along with 3 Zealots and 3 Missionaries and report back to me.",
},
[94441] = {
["o"] = "Speak with Danitha Morr in the keep at Bandarion Keep.",
["d"] = "Please give my thanks to Danitha Morr and tell her that the rest of the Deathguard will hear about the service that the paladins of Bandarion Keep performed for us. \r\n\r\nYou have a lot of promise as a paladin, and I am proud to have those like you among the ranks of the Forsaken. Dark Lady watch over you, N.",
},
[94489] = {
["o"] = "Enter the Nightfang Den and heal 7 druids and find Jorel Windsinger in Shadowgale Forest.",
["d"] = "I have finished the poultices. Quickly, take them to the druids in the cave, north just across the clearing. I know my brethren are in much more dire condition than I. They are likely too injured to heal their own wounds. There are so few of us shen'dorei druids that every life is precious.\r\n\r\nBefore you go, I have a selfish request. My mate, Jorel Windsinger was in dire condition when I left. Please, see to his wounds if he still lives.",
},
[93740] = {
["o"] = "Collect 10 Al'Aketh Windstone Charms from the corpses of Al'Aketh cultists in the Gustberry Lowlands.",
["d"] = "A number of our Windshaper novices were found dead in the Highlands this morning. We can't be certain but there is a strong chance that the Al'Aketh are responsible. Windshapers trade blood for blood, every time.\r\n\r\nHead north and kill any Al'Aketh you encounter. Bring me their windstone prayer charms as proof of the deed. We do not forgive and we do not forget.",
},
[93926] = {
["o"] = "Find Peacekeeper Vaaniel at the western watchtower.",
["d"] = "Whatever reason the cult has for attacking the tower, it's not worth losing our people over.\r\n\r\nI'd like for you to head to the southwest and check in on that watchtower for us. Find the peacekeepers there and tell them to head back to the village. Holding that tower is not worth the lives it would cost and I'd rather concentrate the defenders we do have here to protect our citizens.\r\n\r\nPeacekeeper Vaaniel is in charge; let him know to head back here as quickly as possible. Hurry!",
},
[94568] = {
["o"] = "Speak with Talaanis Shadowsong and observe the conversation.",
["d"] = "The turncoat clearly was afraid of what the cult had planned, enough so to defect and seek our aid. It's truly unfortunate that he is dead and took his secrets to the grave with him.\r\n\r\nWe must discuss this further to determine our next steps.",
},
[354] = {
["o"] = "Bring Gregor's Remains, Nissa's Remains and Thurman's Remains to Coleman Farthing in Brill.",
["d"] = "The Agamand family was the most prosperous family in Tirisfal Glades.  I used to work their mills...before the Plague.\n\nWhen the Scourge first came, the Agamands fortified their home and convinced those in their employ to remain and help them defend.  We were fools, but at least we were loyal fools.\n\nThe Agamands, in their pride, doomed us to undeath.  And now they are minions of the Scourge!\n\nServe the Forsaken by defeating the Agamands who fell to the Plague.  Serve me by bringing me their remains.",
},
[92529] = {
["o"] = "Report to Missionary Jasaan near the entrance to Falaath Village.\r\n\r\nIf you lose your Mark of Akir, speak with Sania Silverstream in Shen'dar Village to regain the effect.",
["d"] = "It gladdens my heart that you wish to serve Al'Akir. Our current trials as a people stem from our own complacency. We grew prideful and took the bounty of the winds for granted. The stagnation that followed is the reason the spirits of the wind abandoned us.\r\n\r\nOnly through acts of contrition may we feel the wind's caress once more. If you seek the fellowship of like-minded shen'dorei, go to Falaath Village and find Missionary Jasaan there. I will mark you so that the faithful will know you as a recruit.",
},
[95350] = {
["o"] = "Travel to Orgrimmar and speak with Thrall in the Valley of Wisdom.",
["d"] = "It's a big world down here, and our new allies are the key to our survival.\r\n\r\nThe Earthen Ring is a member of the \"Horde\", a proud collection of like-minded peoples. The nearby city of Thunder Bluff is a part of the Horde, and further to the east lies the capital of Orgrimmar.\r\n\r\nSeek out the flight master in the center of Thunder Bluff. They will fly you to Orgrimmar where you will make contact with the Horde warchief--Thrall, on behalf of the Windshapers. Winds guide you, N.",
},
[93836] = {
["o"] = "Speak with Talaanis Shadowsong in Valanaar.",
["d"] = "Muln has told me much of the elemental lords and I am afraid that we have good reason to fear Al'Akir. Now that the wards that have hidden Zephras from his view are down, we are utterly defenseless. If he chooses to attack us, we stand no chance against him here in his own domain.\r\n\r\nHigh Elder Shadowsong needs to know of the danger we are in, and more importantly, what our intentions are for our mission to Azeroth. We will find the means to save our home. I swear it.",
},
[94485] = {
["o"] = "Collect 8 Lady's Tear Moss.",
["d"] = "If we are to save my fellows in the Nightclaw Den, I am going to need some ingredients for a poultice. The first and most important is a spindly moss called Lady's Tear. It typically grows on the base of the trees here in Shadowgale.\r\n\r\nThis moss secretes a sticky substance that acts as an antiseptic and is perfect for binding open wounds. I have gathered what little I can reach but I know there is more in this forest.\r\n\r\nGo and be swift. We are going to need a lot if the injured I left behind still live.",
},
[93736] = {
["o"] = "Gather 10 Wind Hollow Essences from Wind Hollows in the Shadowgale Forest.",
["d"] = "The paramount concern of the Windshapers is to better understand why the spirits left us, and what we may be able to do to bring them back. One curious fixture of Shadowgale Forest to the north is the presence of a curious form of wind sprite that some call \"hollows\". We know little of them and why they are there, but we do know that they first started to appear after the spirits of the wind left us.\r\n\r\nI need you to go there and disperse them. Gather the remains and bring them back here.",
},
[92464] = {
["o"] = "Speak to Yala Windwatcher in Thendal Grove.",
["d"] = "Ever since our elemental benefactors left us, it seems that we are simply moving from one unrest to another. The problem we face now is that the manifestations of the winds near the standing stones to the northeast are agitated.\r\n\r\nNot truly self-aware like the sentient wind spirits that once lived here, these simple sprites respond in kind to forces, emotions, and intentions of the creatures around them. \r\n\r\nMy apprentice Yala Windwatcher went to observe them. Seek her out and discover what she's learned.",
},
[92880] = {
["o"] = "Bring Yorna's Report to Valennia Stormfist in Valanaar.",
["d"] = "I suspect it will take a bit of time for us to mop up what's left of the attackers, but our chances are far better now. Head back to Valanaar and let them know that we are stable here now.\r\n\r\nI can't thank you enough for your help. We'd be in much worse shape without you. I asked for reinforcements and it seems that I got a burgeoning hero instead. I'll take that.\r\n\r\nMay the four winds bless you, hunter.",
},
[97245] = {
["o"] = "Find the home of Kuramaa in the Shen'dar Highlands, and defeat the spirit in combat. Bring Kuramaa's Mask to Olariaan Swiftburn in the Gustberry Lowlands when you are victorious.",
["d"] = "The residents of the Shen'dar Highlands speak of an ancient forest sprite called Kuramaa. They say it lives inside of a twisted stump at the summit of a hill near the highlands Anchor Pylon.\r\n\r\nGo to the highlands and find this stump. Rap your fist upon the bark and Kuramaa will appear. Best the spirit in combat, and bring me its wooden mask.\r\n\r\nBe warned however, this entity will be exceptionally resistant to much of your magic. Only the touch of flame will lay low the spirit.",
},
[355] = {
["o"] = "Speak with Magistrate Sevren in Brill.",
["d"] = "You have given me the remains of the Agamands, and satisfied my desire for revenge.  But the Agamand Mills hold a threat to all the Forsaken, not just to me.\n\nI have spoken to Magistrate Sevren of your exploits against the Agamands, and he wishes to speak with you.",
},
[93948] = {
["o"] = "Deliver the Shadowsong Family Signet to Talaanis Shadowsong in Valanaar.",
["d"] = "Since you are going to Valanaar anyway, please deliver the signet ring you recovered from the tower to Talaanis Shadowsong in Valanaar. \r\n\r\nHe will want this back, and more importantly, he will want to learn the fate of his nephew. Talaanis is the High Elder of Zephras Isle and more importantly, he is a good man who is well loved by the people, despite our current hardships. It pains me to think of how he will react to this news. Please express my condolences for his loss.",
},
[93737] = {
["o"] = "Speak with Riaani Nightwind and listen to what he has to say.",
["d"] = "Oh, hello. Ayessa sent you to assist me? Very well then. \r\n\r\nNot sure what an obvious novice like yourself can do, but if you give me a moment to pull my head out of this construct's innards I might have a few ideas of things you can do to help.",
},
[94490] = {
["o"] = "Bring the Ripped Missive to Elegael Thornpaw in the Shadowgale Forest.",
["d"] = "<Tucked behind one of Haalien's bracers is a note that's been slightly torn and bloodstained in your fight. It looks like it contains useful information about the cultist motivations for the attack on the druid den. Elegael would be interested in this intel.>",
},
[92466] = {
["o"] = "Bring a Signet of Akir to Windshaper Boro.",
["d"] = "While we owe much of our prosperity to the elements of wind, the path we walk requires that we obey the call of all four of the primary elements and undertake a trial for each. Before you begin your first trial in earnest however, you must prove the strength of your resolve.\r\n\r\nTravel to the standing stones to the east. A force of Al'Aketh converts has been spotted there and they must be driven off. Confront the cultists there and bring me one of their signets as proof of your deeds.",
},
[92482] = {
["o"] = "Read the Scribbled Note and then speak with Tai'ree Farsight in Thendal Grove.",
["d"] = "While you were away dealing with our vuldren problem, our resident hunter trainer--Tai'ree Farsight--left this note for you. You can find her just over yonder near the center of the village. Read the note then seek her out.",
},
[99153] = {
["o"] = "Find the Hidden Crystal Fragment beneath Shadowvale for Ephram Barbaro.",
["d"] = "Oi, you! Word travels quickly among our ranks. I heard about the work you did with the cultists around the remnants of the battle with Naxxramas.\r\n\r\nProblem is, one of them cultists got away with a piece of the focusing crystal. Seems to still have some juice in it. Best guess we have is it's somewhere beneath Shadowvale. It's either raising 'em or making 'em stronger, and you don't want either one.\r\n\r\nFind that crystal before this gets out of hand.",
},
[99144] = {
["o"] = "Help Bareth Dawnstone escape Crusader's Outpost, and report his safety to Shari Stilwell in Brill.",
["d"] = "Light bless you for finding me. I was on my way from Bandarion Keep to deliver a message to Shari Stilwell in Brill when these monsters captured me. They wield the Light with a hatred in their hearts that makes what's left of my blood seethe. It goes against all we stand for!\r\n\r\n<Bareth Dawnstone steadies himself.>\r\n\r\nOur ranks are thin. If you would aid me in escaping this place, I would be forever grateful.",
},
[97956] = {
["o"] = "Speak with Clyde Kellen in Brill to learn to craft a camping item for your profession once you have shown proficiency in your skill.",
["d"] = "You might not think so, but your skill as a fisherman can actually come in handy at camp.\r\n\r\nI reckon I know someone that can teach you how to craft a Fish Bowl for your camp. You can use this fixture to help provide a bit of joy to yourself and your fellow adventurers. A happy adventurer is a strong adventurer and I'm sure your combat capabilities will reflect that.",
},
[93065] = {
["o"] = "Speak with Valennia Stormfist in the Gustberry Lowlands.",
["d"] = "The Peacekeepers are mobilizing and we are all gearing up to head out. Make whatever preparations you need to make and meet us at the eastern road leading north out of town. We'll have one final check-in with everyone before we move out.",
},
[96897] = {
["o"] = "Kill 8 Dark Neophytes and 8 Dark Enforcers in Tirisfal Glades.",
["d"] = "The Scourge are a blight on our lands, and their living servants are the worst of them. The people of Tirisfal have enough to deal with between the mindless dead and the Scarlet Crusade. If you wish to do some good, help me put an end to this scum.",
},
[93160] = {
["o"] = "Gather 8 Shadowgale Acorns in Shadowgale Forest.",
["d"] = "I do appreciate you stopping by to talk with me! I-If you do want to help out, I could use a bit of help gathering up acorns from the forest floor. I've gathered most of the ones close by but there sure are a lot of raptor-bird things in the forest. It's dangerous out there and I'd rather not become a giant bird's lunch!\r\n\r\nSo if you want, you could maybe gather them for me? I'll make us something tasty if you do!",
},
[92532] = {
["o"] = "Read the Crumpled Note you've been given, then seek out Blademaster Ren inside the Thendal Village watchtower.",
["d"] = "While you were gone our warrior trainer--Blademaster Ren--requested that we send you their way when you returned. She dropped this note off for you as well.\r\n\r\nGive it a read, then find Blademaster Ren inside the village watchtower.",
},
[97965] = {
["o"] = "Speak with Naleeia Tattermend in Shen'dar Village to learn to craft a camping item for your profession once you have shown proficiency in your skill.",
["d"] = "So you've taken up First Aid? That's an honorable... and pragmatic pursuit as a hunter.\r\n\r\nI reckon I know someone that can teach you how to craft a First Aid Kit for your camp. Injuries are a reality in the world of adventuring and offering some much-needed healing at your camp could even save lives.",
},
[94411] = {
["o"] = "Slay 6 High Order Apprentices in Shen'dar Highlands.",
["d"] = "Be warned, members of the High Order have been seen in the vicinity of the standing stones north of the village. We have warned them time and again to not meddle at our sacred sites, but they are growing more bold in pushing us. Prove your resolve to us by going to the standing stones and dispersing them.\r\n\r\nI am loathe to condone outright bloodshed, but do what you must to drive them off. Return to me when it's done.",
},
[94427] = {
["o"] = "Speak to Tanis Alderwood in the Undercity.",
["d"] = "A key tenent of being a paladin is the pursuit of divinity. This is not the pursuit of godhood, but merely the pursuit of good itself, for good's sake. We've all arrived at this place due to tragedy of one form or another, and it would be easy to lose that grace that defined us as paladins in life.\r\n\r\nGo to the Undercity and seek out Tanis Alderwood in the Trade Quarter. They are in need, and they could benefit greatly from some grace.",
},
[356] = {
["o"] = "Kill 8 Bleeding Horrors and 8 Wandering Spirits, then report back to Linnea at her camp.",
["d"] = "The defenders on The Bulwark protecting Tirisfal from the Plaguelands are on constant alert. But sometimes Scourge will slip past them.\n\nOur success at the Bulwark depends on a one-front battle - we cannot allow an attack from the rear, nor can we allow our defenders' supply line to be cut.\n\nAssist the Bulwark. Patrol east and slay any Scourge you find. Spend particular effort at the Balnir Farmstead to the east. It has become a haven for interloping Scourge.",
},
[372] = {
["o"] = "Executor Zygand in the town of Brill wants you to assassinate Captain Melrache and his two bodyguards.",
["d"] = "Scarlet Crusaders have been raiding from the ruined tower in northern Tirisfal, past Faol's Rest.  According to the information we have, a ruthless commander named Captain Melrache is in charge of this evil crew.\n\nI am entrusting you now with a special and dangerous mission.  Slay Melrache and his two bodyguards, in the name of The Dark Lady.",
},
[264] = {
["o"] = "Place Clarice's Pendant on Yuriv's Tomb in Silverpine.",
["d"] = "Filthy scum! Leaves me for his damn crusade. Because \"the Light is the most important thing we have against the threats the undead pose.\"\n\nWell, what about his children?! What about ME?! Night after night I sat patiently waiting for him... always second to his blasted duty!\n\nWell, witness what \"justice\" brings you, N! He's dead and I'm bearing the very thing he was trying to stop!\n\nTake this piece of junk and put it on his tomb at the Sepulcher. I want nothing to do with it anymore... or him!",
},
[94491] = {
["o"] = "Give the missive to Lotheluum in Valanaar and tell him what has transpired.",
["d"] = "It would appear that there is a correspondent hiding somewhere in Valanaar feeding information to the cult. I am clearly in no shape to make the journey, but Lotheluum needs to know what transpired here.\r\n\r\nHe should also know the fate of those who are no longer with us. Thanks to your help I think we can handle the rest of the situation from here, though the damage has been done.\r\n\r\nPlease go swiftly, N. I hope our paths will cross again someday. Until then, I have cultists to slay.",
},
[92467] = {
["o"] = "Find the Rise of Spirits and drink the Earth Sapta.",
["d"] = "A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the strong willed to see the elements as no one else can. Your spirit will be connected to the element the sapta was created for, and only a select few shaman know the recipe.\n\nThe sapta is always drunk in a sacred place, and never anywhere else--remember that.\n\nSeek out the Rise of Spirits up the pass east of here. Drink your sapta there, and... well, you will see what you need to see.",
},
[94013] = {
["o"] = "Use the Taming Rod to tame a Vuldren Alpha in the Gustberry Lowlands. Practice your skills, then return the Taming Rod to Quel'ana Quickgale in Valanaar.",
["d"] = "You've returned triumphant from taming two beasts. It's time now for your last trial. The winds of Zephras whisper of greater challenges ahead. \r\n\r\nTake this Taming Rod and journey to the Gustberry Lowlands. There, tame a Vuldren Alpha and prove your mastery. \r\n\r\nComplete this lesson and you'll be ready to learn the deeper ways of the hunter.",
},
[94978] = {
["o"] = "Use the Taming Rod to tame a Windsong Crawler found near bodies of water. \r\nPractice your skills, then return the Taming Rod to Quel'ana Quickgale in Valanaar.",
["d"] = "Every hunter begins by learning the bond between beast and master. This is your first challenge. In time, you'll tame creatures from every corner of the world, but for now, start with our rivers and lakes on Zephras. \r\n\r\nTake this Taming Rod and seek out a Windsong Crawler.\r\n\r\nShow that you can earn its trust, and begin your path toward true mastery.",
},
[92515] = {
["o"] = "Collect 10 Prideclaw Pelts from the Prideclaws in Shen'dar Highlands.",
["d"] = "As if bandits and mad cultists weren't enough, the hills are thick with prideclaws as well right now. They are starting to encroach on the village borders and growing bolder by the day. It's only a matter of time before someone's pet or child is taken. It would be a mercy for us to cull their numbers now rather than after some tragedy occurs.\r\n\r\nBring me a dozen or so of their pelts. I can turn them into all sorts of goods that will be of aid to the village.",
},
[96101] = {
["o"] = "Sit near Raan's Basic Campfire and wait until you receive the Boosted Rest buff.",
["d"] = "Greetings, hunter. I can see you've got the look of an adventurer about you. This is good. The world needs more of us restless souls, seeking fortune and glory.\r\n\r\nYou'll need to learn to thrive in the wilds to be successful in this line of work. Not sure how your outdoor skills are but I can probably teach you a thing or two, if you'd be apt to learn.\r\n\r\nHave a seat near the fire and get comfortable. I'll walk you through it.",
},
[97242] = {
["o"] = "Take some cuttings from the Cattails and Speargrass growing around the water flows in the Valley of Honor and return to Kor'geld in Yelmak's Alchemy and Potions.",
["d"] = "Yelmak doesn't want his apprentice breaking anything. Well, anything more than he already has.\r\n\r\nHe told me the young mixer in training has too much pride to ask for help when he really needs it. Yelmak wants to give him a taste of a particular home-brewed recipe.\r\n\r\nGather a mix of cattail and speargrass cuttings taken from the plants growing around the water in the Valley of Honor. I'd get them myself, but if I left the shop, Whuut would surely know we're catering to his mood.",
},
},
},
